import { useEffect, useRef, useState } from "react";
import "./../styles/player.css";

const STREAM_URL = "https://stream.zeno.fm/yn65fsaurfhvv";

// Programação de exemplo — troque pelos horários reais da grade
// quando integrar com o sistema de programação da rádio.
const PROGRAMACAO_EXEMPLO = [
  { inicio: 6, fim: 10, nome: "Manhã TOP FM" },
  { inicio: 10, fim: 12, nome: "TOP Hits" },
  { inicio: 12, fim: 14, nome: "TOP Notícias" },
  { inicio: 14, fim: 18, nome: "Tarde Animada" },
  { inicio: 18, fim: 20, nome: "Drive TOP FM" },
  { inicio: 20, fim: 24, nome: "Top da Noite" },
  { inicio: 0, fim: 6, nome: "Madrugada TOP FM" },
];

function getProgramaAtual(hora) {
  return (
    PROGRAMACAO_EXEMPLO.find((p) =>
      p.inicio < p.fim
        ? hora >= p.inicio && hora < p.fim
        : hora >= p.inicio || hora < p.fim
    ) || PROGRAMACAO_EXEMPLO[0]
  );
}

function formatarHora(date) {
  return date.toLocaleTimeString("pt-BR", {
    hour: "2-digit",
    minute: "2-digit",
  });
}

export default function Player() {
  const audioRef = useRef(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [volume, setVolume] = useState(0.8);
  const [agora, setAgora] = useState(new Date());
  // Contagem de ouvintes simulada (sem backend conectado), apenas
  // para dar sensação de transmissão viva — troque por um valor
  // real quando houver uma API de audiência disponível.
  const [ouvintes, setOuvintes] = useState(184);

  useEffect(() => {
    const relogio = setInterval(() => setAgora(new Date()), 1000);
    return () => clearInterval(relogio);
  }, []);

  useEffect(() => {
    const audiencia = setInterval(() => {
      setOuvintes((prev) => {
        const variacao = Math.floor(Math.random() * 7) - 3;
        return Math.max(60, prev + variacao);
      });
    }, 4000);
    return () => clearInterval(audiencia);
  }, []);

  const programaAtual = getProgramaAtual(agora.getHours());

  function togglePlay() {
    const audio = audioRef.current;
    if (!audio || isLoading) return;

    if (isPlaying) {
      // Pausa e descarta o buffer atual — assim, ao retomar, o
      // stream não continua de onde ficou, e sim do momento real
      // da transmissão.
      audio.pause();
      audio.src = "";
      audio.load();
      setIsPlaying(false);
      return;
    }

    setIsLoading(true);

    // Recarrega a fonte com um parâmetro único para evitar que o
    // navegador reaproveite um buffer/cache antigo do stream,
    // garantindo sincronia com o áudio ao vivo da rádio agora.
    audio.src = `${STREAM_URL}?_=${Date.now()}`;
    audio.load();

    const playPromise = audio.play();

    if (playPromise && typeof playPromise.then === "function") {
      playPromise
        .then(() => {
          setIsPlaying(true);
          setIsLoading(false);
        })
        .catch(() => {
          // Reprodução interrompida ou bloqueada pelo navegador —
          // simplesmente volta ao estado pausado, sem quebrar a UI.
          setIsPlaying(false);
          setIsLoading(false);
        });
    } else {
      setIsPlaying(true);
      setIsLoading(false);
    }
  }

  function handleVolumeChange(e) {
    const value = Number(e.target.value);
    setVolume(value);
    if (audioRef.current) {
      audioRef.current.volume = value;
    }
  }

  return (
    <div className="player-card">
      <div className="player-top">
        <span className="player-onair">
          <span className="player-onair-dot" />
          NO AR
        </span>
        <h2>OUÇA AO VIVO</h2>
        <span className="player-clock">{formatarHora(agora)}</span>
      </div>

      <div className="player-meta">
        <span className="player-meta-item">
          <strong>Programa:</strong> {programaAtual.nome}
        </span>
        <span className="player-meta-divider" />
        <span className="player-meta-item player-meta-listeners">
          <span className="player-meta-dot" />
          {ouvintes} ouvintes agora
        </span>
      </div>

      <div className="player-main">
        <button
          type="button"
          className={`player-playbtn ${isPlaying ? "is-playing" : ""}`}
          onClick={togglePlay}
          disabled={isLoading}
          aria-label={isPlaying ? "Pausar transmissão" : "Tocar transmissão"}
        >
          {isLoading ? (
            <svg
              viewBox="0 0 24 24"
              width="24"
              height="24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.5"
              className="player-spinner"
            >
              <circle cx="12" cy="12" r="9" strokeOpacity="0.25" />
              <path d="M21 12a9 9 0 0 0-9-9" strokeLinecap="round" />
            </svg>
          ) : isPlaying ? (
            <svg viewBox="0 0 24 24" width="26" height="26" fill="currentColor">
              <rect x="5" y="4" width="5" height="16" rx="1.5" />
              <rect x="14" y="4" width="5" height="16" rx="1.5" />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24" width="26" height="26" fill="currentColor">
              <path d="M6 4.5v15l13-7.5z" />
            </svg>
          )}
        </button>

        <div className="player-info">
          <span className="player-label">Tocando agora</span>
          <p className="player-track">Dua Lipa</p>

          <div className={`player-eq ${isPlaying ? "is-playing" : ""}`}>
            <span></span>
            <span></span>
            <span></span>
            <span></span>
            <span></span>
          </div>
        </div>
      </div>

      <div className="player-next">
        <span className="player-next-label">A seguir</span>
        <span className="player-next-value">Tarde Animada · às 14h</span>
      </div>

      <div className="player-volume">
        <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
          <path d="M5 9v6h4l5 5V4L9 9H5z" />
        </svg>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={volume}
          onChange={handleVolumeChange}
          aria-label="Volume"
        />
      </div>

      <audio
        ref={audioRef}
        preload="none"
        onPause={() => setIsPlaying(false)}
        onError={() => {
          setIsPlaying(false);
          setIsLoading(false);
        }}
      />

      <button className="player-request">Pedir Música</button>
    </div>
  );
}
